using System.Windows; namespace CloudServer; public partial class AdminWindow:Window { readonly StateStore store; public AdminWindow(StateStore s){InitializeComponent();BrandImage.Source=BrandLogo.Image();store=s;AddUserButton.Click+=(_,__)=>AddUser();EditUserButton.Click+=(_,__)=>EditUser();DeleteUserButton.Click+=(_,__)=>DeleteUser();AddGroupButton.Click+=(_,__)=>AddGroup();EditGroupButton.Click+=(_,__)=>EditGroup();DeleteGroupButton.Click+=(_,__)=>DeleteGroup();AddStorageButton.Click+=(_,__)=>AddStorage();EditStorageButton.Click+=(_,__)=>EditStorage();DeleteStorageButton.Click+=(_,__)=>DeleteStorage();Refresh();} void Refresh(){UserCount.Text=store.State.Users.Count.ToString();StorageCount.Text=store.State.Storage.Count.ToString();UsersGrid.ItemsSource=store.State.Users.Select(u=>new UserRow(u.Id,u.UserName,u.IsAdmin?"Administrator":"Benutzer",Format(u.QuotaBytes))).ToList();GroupsList.ItemsSource=store.State.Groups.Select(g=>new GroupRow(g.Id,g.Name,store.State.Users.Count(u=>u.GroupIds.Contains(g.Id)))).ToList();StorageGrid.ItemsSource=store.State.Storage.Select(x=>new StorageRow(x.Id,x.Name,x.Role,store.State.Users.FirstOrDefault(u=>u.Id==x.UserId)?.UserName??store.State.Groups.FirstOrDefault(g=>g.Id==x.GroupId)?.Name??"Nicht zugewiesen",Format(x.QuotaBytes))).ToList();} static string Format(long b)=>b<=0?"Unbegrenzt":b>=1099511627776L?$"{b/1099511627776d:N2} TB":$"{b/1073741824d:N0} GB"; void AddUser(){var d=new UserDialog{Owner=this};if(d.ShowDialog()!=true)return;if(string.IsNullOrWhiteSpace(d.Password)){System.Windows.MessageBox.Show("Für neue Benutzer ist ein Passwort erforderlich.");return;}if(store.State.Users.Any(x=>x.UserName.Equals(d.UserName,StringComparison.OrdinalIgnoreCase))){System.Windows.MessageBox.Show("Dieser Benutzername ist bereits vergeben.");return;}store.State.Users.Add(new UserAccount{UserName=d.UserName,DisplayName=d.DisplayName,PasswordHash=StateStore.Hash(d.Password),QuotaBytes=d.QuotaBytes});store.Save();Refresh();} void EditUser(){if(UsersGrid.SelectedItem is not UserRow row)return;var u=store.State.Users.FirstOrDefault(x=>x.Id==row.Id);if(u==null)return;var d=new UserDialog(u.UserName,u.DisplayName,u.QuotaBytes){Owner=this};if(d.ShowDialog()!=true)return;if(store.State.Users.Any(x=>x.Id!=u.Id&&x.UserName.Equals(d.UserName,StringComparison.OrdinalIgnoreCase))){System.Windows.MessageBox.Show("Dieser Benutzername ist bereits vergeben.");return;}u.UserName=d.UserName;u.DisplayName=d.DisplayName;u.QuotaBytes=d.QuotaBytes;if(!string.IsNullOrWhiteSpace(d.Password))u.PasswordHash=StateStore.Hash(d.Password);store.Save();Refresh();} void DeleteUser(){if(UsersGrid.SelectedItem is not UserRow row)return;var u=store.State.Users.FirstOrDefault(x=>x.Id==row.Id);if(u==null||u.IsAdmin)return;var owned=store.State.Storage.Count(x=>x.UserId==u.Id);var shares=store.State.Shares.Count(x=>x.OwnerUserId==u.Id||x.TargetUserId==u.Id);var transfers=store.State.Transfers.Count(x=>x.OwnerUserId==u.Id);if(System.Windows.MessageBox.Show($"Benutzer {u.UserName} löschen?\n\nZugeordnete Speicher: {owned}\nFreigaben: {shares}\nTransferlinks: {transfers}\n\nDateien auf den Datenträgern werden NICHT gelöscht. Speicherzuweisungen werden lediglich vom Benutzer gelöst.","Benutzer löschen",MessageBoxButton.YesNo,MessageBoxImage.Warning)!=MessageBoxResult.Yes)return;foreach(var s in store.State.Storage.Where(x=>x.UserId==u.Id))s.UserId=null;store.State.Shares.RemoveAll(x=>x.OwnerUserId==u.Id||x.TargetUserId==u.Id);store.State.Transfers.RemoveAll(x=>x.OwnerUserId==u.Id);store.State.Users.Remove(u);store.Save();Refresh();} void AddGroup(){var d=new GroupDialog(store){Owner=this};if(d.ShowDialog()!=true)return;var g=new CloudGroup{Name=d.GroupName};store.State.Groups.Add(g);foreach(var u in store.State.Users)if(d.UserIds.Contains(u.Id))u.GroupIds.Add(g.Id);store.Save();Refresh();} void EditGroup(){if(GroupsList.SelectedItem is not GroupRow row)return;var g=store.State.Groups.FirstOrDefault(x=>x.Id==row.Id);if(g==null)return;var d=new GroupDialog(store,g){Owner=this};if(d.ShowDialog()!=true)return;g.Name=d.GroupName;foreach(var u in store.State.Users){u.GroupIds.Remove(g.Id);if(d.UserIds.Contains(u.Id))u.GroupIds.Add(g.Id);}store.Save();Refresh();} void DeleteGroup(){if(GroupsList.SelectedItem is not GroupRow row)return;var g=store.State.Groups.FirstOrDefault(x=>x.Id==row.Id);if(g==null)return;if(System.Windows.MessageBox.Show($"Gruppe „{g.Name}“ löschen?","Bestätigen",MessageBoxButton.YesNo)!=MessageBoxResult.Yes)return;foreach(var u in store.State.Users)u.GroupIds.Remove(g.Id);foreach(var s in store.State.Storage.Where(x=>x.GroupId==g.Id)){s.GroupId=null;}store.State.Groups.Remove(g);store.Save();Refresh();}  void AddStorage(){var d=new StorageDialog(store){Owner=this};if(d.ShowDialog()!=true)return;store.State.Storage.Add(new StorageAssignment{Name=d.StorageName,Path=d.StoragePath,Role=d.Role,UserId=d.UserId,GroupId=d.GroupId,QuotaBytes=d.QuotaBytes});store.Save();Refresh();} void EditStorage(){if(StorageGrid.SelectedItem is not StorageRow row)return;var s=store.State.Storage.FirstOrDefault(x=>x.Id==row.Id);if(s==null)return;var d=new StorageDialog(store,s){Owner=this};if(d.ShowDialog()!=true)return;s.Name=d.StorageName;s.Path=d.StoragePath;s.Role=d.Role;s.UserId=d.UserId;s.GroupId=d.GroupId;s.QuotaBytes=d.QuotaBytes;store.Save();Refresh();} void DeleteStorage(){if(StorageGrid.SelectedItem is not StorageRow row)return;var s=store.State.Storage.FirstOrDefault(x=>x.Id==row.Id);if(s==null)return;if(System.Windows.MessageBox.Show($"Speicherzuweisung „{s.Name}“ entfernen?\n\nEs werden keine Dateien gelöscht oder formatiert.","Speicher entfernen",MessageBoxButton.YesNo)!=MessageBoxResult.Yes)return;store.State.Storage.Remove(s);store.Save();Refresh();}  sealed record GroupRow(string Id,string Name,int Members){public override string ToString()=>$"{Name} ({Members})";} sealed record UserRow(string Id,string User,string Role,string Quota); sealed record StorageRow(string Id,string Name,string Role,string Assigned,string Quota); }